        [MenuItem("BubuTown/Integrate Asset Store Modern City Prefabs")]
        public static void IntegrateAssetStoreModernCityPrefabs()
        {
            AssetDatabase.Refresh();
            ConvertImportedMaterialsForUrp();
            GenerateImportedAssetQualityReport();
            GenerateModernVisualQualityGateReport();
            GenerateFreeAssetReplacementRoadmap();
            if (!File.Exists(ScenePath))
            {
                throw new System.Exception("[BubuTown] Missing scene: " + ScenePath);
            }

            EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
            var root = FindRoot();
            if (root == null)
            {
                throw new System.Exception("[BubuTown] Missing scene root.");
            }

            var existing = root.transform.Find("18_AssetStore_ModernCity_Integration");
            if (existing != null)
            {
                Object.DestroyImmediate(existing.gameObject);
            }

            var group = new GameObject("18_AssetStore_ModernCity_Integration");
            group.transform.SetParent(root.transform, false);
            group.transform.localPosition = new Vector3(0f, 0f, 180f);

            var allAssets = FindModernCityAssets();
            if (allAssets.Count == 0)
            {
                CreateStatusBoard(group.transform, "未找到已导入的城市 prefab/FBX。\n请先把资源包导入到 Assets/AssetStoreImported/ModernCity 或常见 Asset Store 目录。");
                EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
                Debug.Log("[BubuTown] No modern city assets found.");
                return;
            }

            var skyscrapers = Filter(allAssets, "building-skyscraper", "skyscraper", "highrise", "high-rise", "tower", "office", "apartment", "eco_building");
            var commercialBuildings = Filter(allAssets, "/commercial/", "commercial", "building-", "building_", "shop", "store", "mall", "retail", "office", "building");
            var suburbanBuildings = Filter(allAssets, "/suburban/", "building-type", "house", "home", "residential", "apartment", "terrace");
            var roadModules = Filter(allAssets, "road-crossroad-line", "road-crossroad", "road-intersection-line", "road-straight", "road-bend-sidewalk", "road-bend", "road-roundabout", "/roads/", "road_", "sidewalk", "crosswalk", "tile");
            var streetDetails = FilterPlayerViewSafeStreetDetails(Filter(allAssets, "traffic-light", "traffic_light", "light-", "road-sign", "planter", "tree-", "fence", "dumpster", "parasol", "awning", "/props/", "bench", "trash", "spotlight", "streetlight"));

            var placedCount = 0;
            placedCount += PlaceDistrict(group.transform, "AssetStore_Skyscraper", skyscrapers, new[]
            {
                new Placement(new Vector3(-44f, 0f, 40f), 180f, 2.55f),
                new Placement(new Vector3(-32f, 0f, 44f), 180f, 2.25f),
                new Placement(new Vector3(-18f, 0f, 45f), 180f, 2.05f),
                new Placement(new Vector3(18f, 0f, 45f), 180f, 2.15f),
                new Placement(new Vector3(33f, 0f, 43f), 180f, 2.45f),
                new Placement(new Vector3(45f, 0f, 31f), -90f, 2.35f),
                new Placement(new Vector3(46f, 0f, 13f), -90f, 2.1f),
                new Placement(new Vector3(45f, 0f, -12f), -90f, 2.5f),
                new Placement(new Vector3(37f, 0f, -43f), 0f, 2.4f),
                new Placement(new Vector3(15f, 0f, -45f), 0f, 2.15f),
                new Placement(new Vector3(-13f, 0f, -45f), 0f, 2.3f),
                new Placement(new Vector3(-38f, 0f, -42f), 0f, 2.55f),
                new Placement(new Vector3(-47f, 0f, -18f), 90f, 2.25f),
                new Placement(new Vector3(-48f, 0f, 10f), 90f, 2.35f),
            });

            placedCount += PlaceDistrict(group.transform, "AssetStore_Commercial_Block", commercialBuildings, new[]
            {
                new Placement(new Vector3(-28f, 0f, 18f), 0f, 1.45f),
                new Placement(new Vector3(-18f, 0f, 16f), 0f, 1.35f),
                new Placement(new Vector3(18f, 0f, 18f), 180f, 1.4f),
                new Placement(new Vector3(29f, 0f, 16f), 180f, 1.3f),
                new Placement(new Vector3(-29f, 0f, -16f), 0f, 1.45f),
                new Placement(new Vector3(-17f, 0f, -18f), 0f, 1.35f),
                new Placement(new Vector3(17f, 0f, -18f), 180f, 1.45f),
                new Placement(new Vector3(29f, 0f, -16f), 180f, 1.35f),
                new Placement(new Vector3(-8f, 0f, 37f), 180f, 1.3f),
                new Placement(new Vector3(5f, 0f, 37f), 180f, 1.45f),
                new Placement(new Vector3(-6f, 0f, -37f), 0f, 1.4f),
                new Placement(new Vector3(8f, 0f, -37f), 0f, 1.35f),
            });

            placedCount += PlaceDistrict(group.transform, "AssetStore_Neighborhood_Modernized", suburbanBuildings, new[]
            {
                new Placement(new Vector3(-36f, 0f, 4f), 90f, 1.25f),
                new Placement(new Vector3(-38f, 0f, -7f), 90f, 1.2f),
                new Placement(new Vector3(-36f, 0f, 23f), 90f, 1.18f),
                new Placement(new Vector3(36f, 0f, 25f), -90f, 1.18f),
                new Placement(new Vector3(36f, 0f, 6f), -90f, 1.15f),
                new Placement(new Vector3(36f, 0f, -25f), -90f, 1.18f),
                new Placement(new Vector3(-24f, 0f, -29f), 0f, 1.15f),
