        [MenuItem("BubuTown/Repair Imported City Magenta Materials")]
        public static void RepairImportedCityMagentaMaterials()
        {
            AssetDatabase.Refresh();
            var beforeSamples = new List<string>();
            var brokenBefore = CountBrokenImportedMaterials(beforeSamples);
            if (File.Exists(ScenePath))
            {
                EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
                brokenBefore += CountBrokenSceneRendererMaterials(beforeSamples);
            }

            ConvertImportedMaterialsForUrp();
            var sceneFallbackRepairs = 0;
            var sceneFallbackSamples = new List<string>();
            if (File.Exists(ScenePath))
            {
                EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
                sceneFallbackRepairs = RepairBrokenSceneRendererMaterials(sceneFallbackSamples);
            }

            GenerateImportedAssetQualityReport();

            var afterSamples = new List<string>();
            var brokenAfter = CountBrokenImportedMaterials(afterSamples);
            if (File.Exists(ScenePath))
            {
                EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
                brokenAfter += CountBrokenSceneRendererMaterials(afterSamples);
            }

            WriteMagentaMaterialRepairReport(brokenBefore, brokenAfter, sceneFallbackRepairs, beforeSamples, sceneFallbackSamples, afterSamples);
            GenerateModernVisualQualityGateReport();
            Debug.Log("[BubuTown] Magenta material repair report written: " + MagentaMaterialRepairReportPath);
        }

        private static void ConvertImportedMaterialsForUrp()
        {
            ConfigureImportedModelQuality();
            ConfigureImportedTextureQuality();
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Universal Render Pipeline/Simple Lit") ?? Shader.Find("Standard");
            if (litShader == null)
            {
                Debug.LogWarning("[BubuTown] No compatible lit shader found for imported materials.");
                return;
            }

            var converted = 0;
            foreach (var root in SearchRoots)
            {
                if (!AssetDatabase.IsValidFolder(root))
                {
                    continue;
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Material", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var material = AssetDatabase.LoadAssetAtPath<Material>(path);
                    if (material == null)
                    {
                        continue;
                    }

                    var color = NormalizeImportedCityColor(path, material, ReadMaterialColor(material));
                    var mainTexture = ReadMaterialTexture(material);
                    var isTransparent = color.a < 0.99f || material.name.ToLowerInvariant().Contains("glass");
                    material.shader = litShader;
                    WriteMaterialColor(material, color);
                    WriteMaterialTexture(material, mainTexture);
                    ConfigureMaterialSurface(material, isTransparent);
                    ConfigureImportedEmission(material);
                    material.enableInstancing = true;
                    EditorUtility.SetDirty(material);
                    converted++;
                }
            }

            if (converted > 0)
            {
                AssetDatabase.SaveAssets();
                AssetDatabase.Refresh();
            }

            Debug.Log("[BubuTown] Converted imported city materials for URP: " + converted);
        }

        private static void ConfigureImportedTextureQuality()
        {
            var changed = 0;
            foreach (var root in SearchRoots)
            {
                if (!AssetDatabase.IsValidFolder(root))
                {
                    continue;
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
                    if (importer == null)
                    {
                        continue;
                    }

                    var dirty = false;
                    if (importer.filterMode != FilterMode.Trilinear)
                    {
                        importer.filterMode = FilterMode.Trilinear;
                        dirty = true;
                    }

                    if (importer.anisoLevel < 8)
                    {
                        importer.anisoLevel = 8;
                        dirty = true;
                    }

                    if (!importer.mipmapEnabled)
                    {
                        importer.mipmapEnabled = true;
                        dirty = true;
                    }

                    if (importer.textureCompression != TextureImporterCompression.Uncompressed)
                    {
                        importer.textureCompression = TextureImporterCompression.Uncompressed;
                        dirty = true;
                    }

                    if (dirty)
                    {
                        importer.SaveAndReimport();
                        changed++;
                    }
                }
            }

            Debug.Log("[BubuTown] Smoothed imported city texture filtering: " + changed);
        }

        private static void ConfigureImportedModelQuality()
        {
            var changed = 0;
            foreach (var root in SearchRoots)
            {
                if (!AssetDatabase.IsValidFolder(root))
                {
                    continue;
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Model", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var importer = AssetImporter.GetAtPath(path) as ModelImporter;
                    if (importer == null)
                    {
                        continue;
                    }

                    var dirty = false;
                    if (importer.meshCompression != ModelImporterMeshCompression.Off)
                    {
                        importer.meshCompression = ModelImporterMeshCompression.Off;
                        dirty = true;
                    }

                    if (importer.importNormals != ModelImporterNormals.Calculate)
                    {
                        importer.importNormals = ModelImporterNormals.Calculate;
                        dirty = true;
                    }

                    if (importer.normalCalculationMode != ModelImporterNormalCalculationMode.AreaAndAngleWeighted)
                    {
                        importer.normalCalculationMode = ModelImporterNormalCalculationMode.AreaAndAngleWeighted;
                        dirty = true;
                    }

                    if (importer.normalSmoothingAngle < 65f)
                    {
                        importer.normalSmoothingAngle = 65f;
                        dirty = true;
                    }

                    if (importer.importTangents != ModelImporterTangents.CalculateMikk)
                    {
                        importer.importTangents = ModelImporterTangents.CalculateMikk;
                        dirty = true;
                    }

                    if (!importer.isReadable)
                    {
                        importer.isReadable = true;
                        dirty = true;
                    }

                    if (!importer.optimizeMeshPolygons)
                    {
                        importer.optimizeMeshPolygons = true;
                        dirty = true;
                    }

                    if (!importer.optimizeMeshVertices)
                    {
                        importer.optimizeMeshVertices = true;
                        dirty = true;
                    }

                    if (dirty)
                    {
                        importer.SaveAndReimport();
                        changed++;
                    }
                }
            }

            Debug.Log("[BubuTown] Smoothed imported city model import settings: " + changed);
        }

        [MenuItem("BubuTown/Generate Imported City Asset Quality Report")]
        public static void GenerateImportedAssetQualityReport()
        {
            var textureCount = 0;
            var pointFilterCount = 0;
            var lowAnisoCount = 0;
            var mipmapOffCount = 0;
            var compressedTextureCount = 0;
            var materialCount = 0;
            var brokenShaderCount = 0;
            var modelCount = 0;
            var modelImporterCount = 0;
            var compressedMeshCount = 0;
            var nonCalculatedNormalCount = 0;
            var nonMikkTangentCount = 0;
            var unreadableModelCount = 0;
            var prefabCount = 0;
            var samples = new List<string>();

            foreach (var root in SearchRoots)
            {
                if (!AssetDatabase.IsValidFolder(root))
                {
                    continue;
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
                    var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
                    textureCount++;
                    if (texture != null && texture.filterMode == FilterMode.Point)
                    {
                        pointFilterCount++;
                        AddSample(samples, "Point filter texture: " + path);
                    }

                    if (texture != null && texture.anisoLevel < 8)
                    {
                        lowAnisoCount++;
                        AddSample(samples, "Low anisotropic texture: " + path + " aniso=" + texture.anisoLevel);
                    }

                    if (importer != null && !importer.mipmapEnabled)
                    {
                        mipmapOffCount++;
                        AddSample(samples, "Mipmap disabled texture: " + path);
                    }

                    if (importer != null && importer.textureCompression != TextureImporterCompression.Uncompressed)
                    {
                        compressedTextureCount++;
                        AddSample(samples, "Compressed texture: " + path);
                    }
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Material", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var material = AssetDatabase.LoadAssetAtPath<Material>(path);
                    materialCount++;
                    if (material == null || material.shader == null || material.shader.name.Contains("Hidden/InternalErrorShader"))
                    {
                        brokenShaderCount++;
                        AddSample(samples, "Broken shader material: " + path);
                    }
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Model", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var importer = AssetImporter.GetAtPath(path) as ModelImporter;
                    modelCount++;
                    if (importer == null)
                    {
                        continue;
                    }

                    modelImporterCount++;
                    if (importer.meshCompression != ModelImporterMeshCompression.Off)
                    {
                        compressedMeshCount++;
                        AddSample(samples, "Compressed mesh model: " + path);
                    }

                    if (importer.importNormals != ModelImporterNormals.Calculate || importer.normalCalculationMode != ModelImporterNormalCalculationMode.AreaAndAngleWeighted || importer.normalSmoothingAngle < 65f)
                    {
                        nonCalculatedNormalCount++;
                        AddSample(samples, "Model normals need smoothing: " + path);
                    }

                    if (importer.importTangents != ModelImporterTangents.CalculateMikk)
                    {
                        nonMikkTangentCount++;
                        AddSample(samples, "Model tangents are not MikkTSpace: " + path);
                    }

                    if (!importer.isReadable)
                    {
                        unreadableModelCount++;
                        AddSample(samples, "Model not readable for future polish tools: " + path);
                    }
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Prefab", new[] { root }))
                {
                    prefabCount++;
                }
            }

            Directory.CreateDirectory(Path.GetDirectoryName(QualityReportPath));
            File.WriteAllText(QualityReportPath, BuildQualityReport(textureCount, pointFilterCount, lowAnisoCount, mipmapOffCount, compressedTextureCount, materialCount, brokenShaderCount, modelCount, modelImporterCount, compressedMeshCount, nonCalculatedNormalCount, nonMikkTangentCount, unreadableModelCount, prefabCount, samples), Encoding.UTF8);
            AssetDatabase.ImportAsset(QualityReportPath);
            AssetDatabase.Refresh();
            Debug.Log("[BubuTown] Imported city asset quality report written: " + QualityReportPath);
        }

        [MenuItem("BubuTown/Generate Modern Visual Quality Gate Report")]
        public static void GenerateModernVisualQualityGateReport()
        {
            var assetReport = File.Exists(QualityReportPath) ? File.ReadAllText(QualityReportPath) : string.Empty;
            var previewReport = File.Exists(PreviewAnomalyReportPath) ? File.ReadAllText(PreviewAnomalyReportPath) : string.Empty;
            var repairReport = File.Exists(MagentaMaterialRepairReportPath) ? File.ReadAllText(MagentaMaterialRepairReportPath) : string.Empty;
            var urpReport = File.Exists(UrpProjectConfigurationReportPath) ? File.ReadAllText(UrpProjectConfigurationReportPath) : string.Empty;
            var integratedKitReports = Directory.Exists("Assets/BubuTown/Docs")
                ? Directory.GetFiles("Assets/BubuTown/Docs", "AppliedFree*PrefabKitReport.md").Length
                : 0;

            var assetGatePass = assetReport.Contains("PASS: imported city assets are configured for non-pixelated, smooth URP preview use.");
            var previewGatePass = previewReport.Contains("Overall: PASS");
            var noPointFilter = assetReport.Contains("- Point-filter textures: 0");
            var noLowAniso = assetReport.Contains("- Textures with anisotropic filtering below 8: 0");
            var mipmapsOn = assetReport.Contains("- Textures with mipmaps disabled: 0");
            var noCompressedTextures = assetReport.Contains("- Compressed textures: 0");
            var noBrokenShaders = assetReport.Contains("- Materials using missing or Hidden/InternalErrorShader: 0");
            var repairGatePass = repairReport.Contains("- Gate: PASS");
            var urpProjectConfigured = urpReport.Contains("PASS: project-level render pipeline settings now point at the Bubu Town URP asset.");
            var noBrokenPreview = previewReport.Contains("Magenta %") && !previewReport.Contains("| CHECK |") && !previewReport.Contains("| MISSING |");
            var enoughAppliedKits = integratedKitReports >= 10;

            var pass = assetGatePass
                && previewGatePass
                && noPointFilter
                && noLowAniso
                && mipmapsOn
                && noCompressedTextures
                && noBrokenShaders
                && repairGatePass
                && urpProjectConfigured
                && noBrokenPreview
                && enoughAppliedKits;

            var report = new StringBuilder();
            report.AppendLine("# Modern Visual Quality Gate Report");
            report.AppendLine();
            report.AppendLine("Generated by `BubuTownAssetStoreCityIntegrator` to keep the prototype moving toward a smooth modern city with no obvious pixelated import settings or magenta shader regressions.");
            report.AppendLine();
            report.AppendLine("## Gate Summary");
            report.AppendLine();
            report.AppendLine("- Imported asset quality gate: " + Gate(assetGatePass));
            report.AppendLine("- Preview anomaly gate: " + Gate(previewGatePass));
            report.AppendLine("- Point-filter textures: " + Gate(noPointFilter));
            report.AppendLine("- Texture anisotropic filtering >= 8: " + Gate(noLowAniso));
            report.AppendLine("- Texture mipmaps enabled: " + Gate(mipmapsOn));
            report.AppendLine("- Uncompressed imported textures: " + Gate(noCompressedTextures));
            report.AppendLine("- No missing/InternalErrorShader materials: " + Gate(noBrokenShaders));
            report.AppendLine("- Magenta material repair pass: " + Gate(repairGatePass));
            report.AppendLine("- Unity 6 URP project configuration: " + Gate(urpProjectConfigured));
            report.AppendLine("- No preview CHECK/MISSING rows: " + Gate(noBrokenPreview));
            report.AppendLine("- Applied real prefab kit reports found: " + integratedKitReports + " (" + Gate(enoughAppliedKits) + ")");
            report.AppendLine();
            report.AppendLine("## Source Reports");
            report.AppendLine();
            report.AppendLine("- `ImportedCityAssetQualityReport.md`");
            report.AppendLine("- `PreviewAnomalyReport.md`");
            report.AppendLine("- `MagentaMaterialRepairReport.md`");
            report.AppendLine("- `UrpProjectConfigurationReport.md`");
            report.AppendLine("- `AppliedFree*PrefabKitReport.md`");
            report.AppendLine();
            report.AppendLine("## Current Gate");
            report.AppendLine();
            report.AppendLine(pass
                ? "PASS: current imported city assets and generated previews satisfy the modern smooth-asset quality gate."
                : "CHECK: inspect the source reports before treating the current city pass as visually clean.");

            Directory.CreateDirectory(Path.GetDirectoryName(ModernVisualQualityGateReportPath));
            File.WriteAllText(ModernVisualQualityGateReportPath, report.ToString(), Encoding.UTF8);
            AssetDatabase.ImportAsset(ModernVisualQualityGateReportPath);
            AssetDatabase.Refresh();
            Debug.Log("[BubuTown] Modern visual quality gate report written: " + ModernVisualQualityGateReportPath);
        }

