            var streetDetails = FilterPlayerViewSafeStreetDetails(Filter(allAssets, "traffic-light", "traffic_light", "light-", "road-sign", "planter", "tree-", "fence", "dumpster", "parasol", "awning", "/props/", "bench", "trash", "spotlight", "streetlight"));

