        private static int CountBrokenImportedMaterials(List<string> samples)
        {
            var broken = 0;
            foreach (var root in SearchRoots)
            {
                if (!AssetDatabase.IsValidFolder(root))
                {
                    continue;
                }

                foreach (var guid in AssetDatabase.FindAssets("t:Material", new[] { root }))
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var material = AssetDatabase.LoadAssetAtPath<Material>(path);
                    if (IsMaterialVisiblyBroken(material))
                    {
                        broken++;
                        AddSample(samples, path);
                    }
                }
            }

            return broken;
        }

        private static int CountBrokenSceneRendererMaterials(List<string> samples)
        {
            var broken = 0;
            var renderers = Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);
            foreach (var renderer in renderers)
            {
                foreach (var material in renderer.sharedMaterials)
                {
                    if (!IsMaterialVisiblyBroken(material))
                    {
                        continue;
                    }

                    broken++;
                    var assetPath = material != null ? AssetDatabase.GetAssetPath(material) : string.Empty;
                    AddSample(samples, "Scene renderer `" + renderer.gameObject.name + "` material `" + (material != null ? material.name : "Missing") + "`" + (string.IsNullOrEmpty(assetPath) ? string.Empty : " source: `" + assetPath + "`"));
                }
            }

            return broken;
        }

        private static int RepairBrokenSceneRendererMaterials(List<string> samples)
        {
            var repairs = 0;
            var dirtyScene = false;
            var renderers = Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);
            foreach (var renderer in renderers)
            {
                var sharedMaterials = renderer.sharedMaterials;
                var changed = false;
                for (var i = 0; i < sharedMaterials.Length; i++)
                {
                    if (!IsMaterialVisiblyBroken(sharedMaterials[i]))
                    {
                        continue;
                    }

                    var fallback = FindSceneRendererFallbackMaterial(renderer.gameObject.name, sharedMaterials[i]);
                    if (fallback == null)
                    {
                        continue;
                    }

                    AddSample(samples, "Renderer `" + renderer.gameObject.name + "` slot " + i + " -> `" + fallback.name + "`");
                    sharedMaterials[i] = fallback;
                    changed = true;
                    repairs++;
                }

                if (!changed)
                {
                    continue;
                }

                renderer.sharedMaterials = sharedMaterials;
                EditorUtility.SetDirty(renderer);
                dirtyScene = true;
            }

            if (dirtyScene)
            {
                EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
                EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
            }

            return repairs;
        }

        private static Material FindSceneRendererFallbackMaterial(string rendererName, Material brokenMaterial)
        {
            var key = (rendererName + " " + (brokenMaterial != null ? brokenMaterial.name : string.Empty)).ToLowerInvariant();
            if (key.Contains("road") || key.Contains("asphalt") || key.Contains("lane") || key.Contains("crosswalk"))
            {
                return LoadFallbackMaterial("Roads.mat", "Asphalt_Dark_Gray.mat", "Color.mat");
            }

            if (key.Contains("sidewalk") || key.Contains("tile") || key.Contains("paving") || key.Contains("plaza") || key.Contains("floor"))
            {
                return LoadFallbackMaterial("Tile_1.mat", "Color.mat");
            }

            if (key.Contains("glass") || key.Contains("window") || key.Contains("tower") || key.Contains("building"))
            {
                return LoadFallbackMaterial("Glass.mat", "Color_Glossy.mat", "Color.mat");
            }

            if (key.Contains("car") || key.Contains("van") || key.Contains("vehicle") || key.Contains("ev"))
            {
                return LoadFallbackMaterial("Car_Color.mat", "Color_Glossy.mat", "Color.mat");
            }

            if (key.Contains("billboard") || key.Contains("sign") || key.Contains("banner") || key.Contains("totem"))
            {
                return LoadFallbackMaterial("Billboard.mat", "Road_Signs.mat", "Color.mat");
            }

            if (key.Contains("palm") || key.Contains("bush") || key.Contains("tree") || key.Contains("grass") || key.Contains("green"))
            {
                return LoadFallbackMaterial("Grass.mat", "Color.mat");
            }

            if (key.Contains("metal") || key.Contains("rail") || key.Contains("frame") || key.Contains("light"))
            {
                return LoadFallbackMaterial("Metal.mat", "Color_Glossy.mat", "Color.mat");
            }

            return LoadFallbackMaterial("Color.mat", "Color_Glossy.mat");
        }

        private static Material LoadFallbackMaterial(params string[] materialNames)
        {
            foreach (var materialName in materialNames)
            {
                var material = AssetDatabase.LoadAssetAtPath<Material>("Assets/ithappy/Cartoon_City_Free/Materials/" + materialName);
                if (material != null && !IsMaterialVisiblyBroken(material))
                {
                    return material;
                }
            }

            return null;
        }

        private static bool IsMaterialVisiblyBroken(Material material)
        {
            if (material == null || material.shader == null || material.shader.name.Contains("Hidden/InternalErrorShader"))
            {
                return true;
            }

            return IsNearMagenta(ReadMaterialColor(material));
        }

        private static bool IsNearMagenta(Color color)
        {
            return color.r > 0.9f && color.g < 0.08f && color.b > 0.9f;
        }

        private static void WriteMagentaMaterialRepairReport(int brokenBefore, int brokenAfter, int sceneFallbackRepairs, List<string> beforeSamples, List<string> sceneFallbackSamples, List<string> afterSamples)
        {
            var report = new StringBuilder();
            report.AppendLine("# Magenta Material Repair Report");
            report.AppendLine();
            report.AppendLine("Generated by `BubuTownAssetStoreCityIntegrator` after running the imported city URP material repair pass.");
            report.AppendLine();
            report.AppendLine("## Summary");
            report.AppendLine();
            report.AppendLine("- Broken/InternalErrorShader materials before repair: " + brokenBefore);
            report.AppendLine("- Broken/InternalErrorShader materials after repair: " + brokenAfter);
            report.AppendLine("- Imported material target shader: Universal Render Pipeline Lit/Simple Lit, falling back to Standard only if URP shaders are unavailable.");
            report.AppendLine("- Texture quality pass: trilinear filtering, anisotropic filtering, mipmaps and uncompressed import settings are refreshed during this repair.");
            report.AppendLine("- Scene renderer fallback material replacements: " + sceneFallbackRepairs);
            report.AppendLine("- Gate: " + Gate(brokenAfter == 0));
            report.AppendLine();
            report.AppendLine("## Before Samples");
            report.AppendLine();
            AppendRepairSamples(report, beforeSamples);
            report.AppendLine();
            report.AppendLine("## Scene Renderer Fallback Samples");
            report.AppendLine();
            AppendRepairSamples(report, sceneFallbackSamples);
            report.AppendLine();
            report.AppendLine("## After Samples");
            report.AppendLine();
            AppendRepairSamples(report, afterSamples);

            Directory.CreateDirectory(Path.GetDirectoryName(MagentaMaterialRepairReportPath));
            File.WriteAllText(MagentaMaterialRepairReportPath, report.ToString(), Encoding.UTF8);
            AssetDatabase.ImportAsset(MagentaMaterialRepairReportPath);
            AssetDatabase.Refresh();
        }

        private static void AppendRepairSamples(StringBuilder report, List<string> samples)
        {
            if (samples.Count == 0)
            {
                report.AppendLine("- None.");
                return;
            }

            foreach (var sample in samples)
            {
                report.AppendLine("- `" + sample + "`");
            }
        }

        private static string Gate(bool pass)
        {
            return pass ? "PASS" : "CHECK";
        }

        private static void AddSample(List<string> samples, string sample)
        {
            if (samples.Count < 24)
            {
                samples.Add(sample);
            }
        }

        private static Color ReadMaterialColor(Material material)
        {
            if (material.HasProperty("_BaseColor"))
            {
                return material.GetColor("_BaseColor");
            }

            return material.HasProperty("_Color") ? material.GetColor("_Color") : Color.white;
        }

        private static Texture ReadMaterialTexture(Material material)
        {
            if (material.HasProperty("_BaseMap"))
            {
                return material.GetTexture("_BaseMap");
            }

            return material.HasProperty("_MainTex") ? material.GetTexture("_MainTex") : null;
        }

        private static Color NormalizeImportedCityColor(string path, Material material, Color color)
        {
            var lower = (path + "/" + material.name).ToLowerInvariant();
            if (lower.Contains("glass"))
            {
                return new Color(0.38f, 0.68f, 0.82f, Mathf.Min(color.a, 0.72f));
            }

            if (lower.Contains("road") || lower.Contains("asphalt"))
            {
                return new Color(0.08f, 0.09f, 0.10f, color.a);
            }

            if (lower.Contains("metal"))
            {
                return new Color(0.45f, 0.48f, 0.50f, color.a);
            }

            if (lower.Contains("emissive"))
            {
                return new Color(0.78f, 0.64f, 0.38f, 1f);
            }

            if (color.r > 0.9f && color.g > 0.8f && color.b < 0.35f)
            {
                return new Color(0.82f, 0.66f, 0.36f, color.a);
            }

            if (color.r > 0.9f && color.g < 0.45f && color.b > 0.55f)
            {
                return new Color(0.74f, 0.46f, 0.58f, color.a);
            }

            if (color.r > 0.92f && color.g > 0.92f && color.b > 0.92f)
            {
                return new Color(0.78f, 0.80f, 0.78f, color.a);
            }

            return color;
        }

        private static void WriteMaterialColor(Material material, Color color)
        {
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", color);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", color);
            }
        }

        private static void WriteMaterialTexture(Material material, Texture texture)
        {
            if (texture == null)
            {
                return;
            }

            if (material.HasProperty("_BaseMap"))
            {
                material.SetTexture("_BaseMap", texture);
            }

            if (material.HasProperty("_MainTex"))
            {
                material.SetTexture("_MainTex", texture);
            }
        }

        private static void ConfigureMaterialSurface(Material material, bool isTransparent)
        {
            if (material.HasProperty("_Metallic"))
            {
                material.SetFloat("_Metallic", material.name.ToLowerInvariant().Contains("metal") ? 0.55f : 0f);
            }

            if (material.HasProperty("_Smoothness"))
            {
                material.SetFloat("_Smoothness", material.name.ToLowerInvariant().Contains("glass") ? 0.78f : 0.35f);
            }

            if (isTransparent && material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 1f);
                material.SetFloat("_Blend", 0f);
                material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                material.SetInt("_ZWrite", 0);
                material.renderQueue = 3000;
                material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            }
            else if (material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 0f);
                material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.One);
                material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.Zero);
                material.SetInt("_ZWrite", 1);
                material.renderQueue = -1;
                material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
            }
        }

        private static void ConfigureImportedEmission(Material material)
        {
            if (!material.HasProperty("_EmissionColor"))
            {
                return;
            }

            var lowerName = material.name.ToLowerInvariant();
            if (lowerName.Contains("emissive") || lowerName.Contains("headlight") || lowerName.Contains("taillight"))
            {
                material.EnableKeyword("_EMISSION");
                material.SetColor("_EmissionColor", new Color(0.18f, 0.14f, 0.07f, 1f));
            }
            else
            {
                material.DisableKeyword("_EMISSION");
                material.SetColor("_EmissionColor", Color.black);
            }
        }

        private static List<string> FindModernCityAssets()
        {
            var result = new List<string>();
            foreach (var root in SearchRoots)
            {
                if (!AssetDatabase.IsValidFolder(root))
                {
                    continue;
                }

                var guids = new List<string>();
                guids.AddRange(AssetDatabase.FindAssets("t:Prefab", new[] { root }));
                guids.AddRange(AssetDatabase.FindAssets("t:Model", new[] { root }));
                foreach (var guid in guids)
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    var lower = path.ToLowerInvariant();
                    if (lower.Contains("_wheel_") || lower.Contains("spoiler") || lower.Contains("nightlight") || lower.Contains("/meshes/") || lower.Contains("/billboards/") || lower.Contains("billboard") || lower.Contains("graffiti") || lower.Contains("/cars/") || lower.Contains("car_") || lower.Contains("van_") || lower.Contains("bus_"))
                    {
                        continue;
                    }

                    if (IsPreferredModelPath(lower) && (lower.Contains("building") || lower.Contains("tower") || lower.Contains("highrise") || lower.Contains("office") || lower.Contains("apartment") || lower.Contains("shop") || lower.Contains("store") || lower.Contains("mall") || lower.Contains("retail") || lower.Contains("city") || lower.Contains("house") || lower.Contains("road") || lower.Contains("sidewalk") || lower.Contains("crosswalk") || lower.Contains("tile") || lower.Contains("light") || lower.Contains("planter") || lower.Contains("traffic") || lower.Contains("fence") || lower.Contains("tree") || lower.Contains("sign") || lower.Contains("prop") || lower.Contains("bench") || lower.Contains("billboard")))
                    {
                        result.Add(path);
                    }
                }
            }

            result.Sort(CompareAssetPriority);
            return result;
        }

        private static bool IsPreferredModelPath(string lowerPath)
        {
            if (lowerPath.EndsWith(".prefab"))
            {
                return true;
            }

            return lowerPath.EndsWith(".fbx");
        }

        private static List<string> Filter(List<string> source, params string[] terms)
        {
            var result = new List<string>();
            foreach (var path in source)
            {
                var lower = path.ToLowerInvariant();
                foreach (var term in terms)
                {
                    if (lower.Contains(term))
                    {
                        result.Add(path);
                        break;
                    }
                }
            }
            result.Sort(CompareAssetPriority);
            return result;
        }

        private static List<string> FilterPlayerViewSafeStreetDetails(List<string> source)
        {
            var result = new List<string>();
            foreach (var path in source)
            {
                var lower = path.ToLowerInvariant();
                if (IsBulkyImportedStreetLight(lower))
                {
                    continue;
                }

                result.Add(path);
            }

            result.Sort(CompareAssetPriority);
            return result;
        }

        private static bool IsBulkyImportedStreetLight(string lowerPath)
        {
            return lowerPath.Contains("spotlight")
                || lowerPath.Contains("traffic_light")
                || lowerPath.Contains("traffic-light")
                || lowerPath.Contains("construction-light")
                || lowerPath.Contains("light-square")
                || lowerPath.Contains("light-curved")
                || lowerPath.Contains("hanging");
        }

        private static int CompareAssetPriority(string a, string b)
        {
            var scoreCompare = AssetPriorityScore(b).CompareTo(AssetPriorityScore(a));
            return scoreCompare != 0 ? scoreCompare : string.CompareOrdinal(a, b);
        }

        private static int AssetPriorityScore(string path)
        {
            var lower = path.ToLowerInvariant();
            var score = 0;
            if (lower.Contains("/ithappy/"))
            {
                score += 100;
            }

            if (lower.EndsWith(".prefab"))
            {
                score += 25;
            }

            if (lower.Contains("futuristic") || lower.Contains("eco_building"))
            {
                score += 12;
            }

            if (lower.Contains("building-skyscraper"))
            {
                score += 6;
            }

            return score;
        }

        private static int PlaceDistrict(Transform parent, string prefix, List<string> assets, Placement[] placements)
        {
            var placed = 0;
            if (assets.Count == 0)
            {
                return placed;
            }

            for (var i = 0; i < placements.Length; i++)
            {
                var asset = assets[i % assets.Count];
                var placement = placements[i];
                if (PlaceAsset(asset, parent, prefix + "_" + i, placement.Position, placement.Yaw, placement.Scale))
                {
                    placed++;
                }
            }

            return placed;
        }

