        private static int PlaceCuratedAsset(Transform parent, string prefix, Vector3 position, float yaw, float scaleMultiplier, List<string> reportEntries, params string[] candidatePaths)
        {
            var path = FirstExistingAsset(candidatePaths);
            if (string.IsNullOrEmpty(path))
            {
                CreateShowcaseMarker(parent, prefix + "_Missing_Asset_Socket", position + new Vector3(0f, 0.35f, -0.75f));
                reportEntries.Add("- `MISSING` " + prefix + " candidates: " + string.Join(", ", candidatePaths));
                return 0;
            }

            if (!PlaceAsset(path, parent, prefix, position, yaw, scaleMultiplier))
            {
                CreateShowcaseMarker(parent, prefix + "_Failed_Import_Socket", position + new Vector3(0f, 0.35f, -0.75f));
                reportEntries.Add("- `FAILED` " + prefix + " source: `" + path + "`");
                return 0;
            }

            CreateShowcaseMarker(parent, prefix + "_Prefab_Source_" + Path.GetFileNameWithoutExtension(path), position + new Vector3(0f, 0.35f, -0.95f));
            reportEntries.Add("- `PLACED` " + prefix + " source: `" + path + "`");
            return 1;
        }

        private static void WriteCuratedShowcaseReport(int placed, List<string> entries)
        {
            var report = new StringBuilder();
            report.AppendLine("# Curated Free Prefab Integration Report");
            report.AppendLine();
            report.AppendLine("Generated by `BubuTownAssetStoreCityIntegrator` after creating the visible Cartoon City Free showcase.");
            report.AppendLine();
            report.AppendLine("## Summary");
            report.AppendLine();
            report.AppendLine("- Showcase group: `18_AssetStore_ModernCity_Integration/Curated_CartoonCity_Free_Visible_Prefab_Showcase`");
            report.AppendLine("- Curated assets placed: " + placed);
            report.AppendLine("- Policy: free/public-safe imported city prefabs only; no private IP skins or copyrighted public assets.");
            report.AppendLine();
            report.AppendLine("## Entries");
            report.AppendLine();
            foreach (var entry in entries)
            {
                report.AppendLine(entry);
            }

            Directory.CreateDirectory(Path.GetDirectoryName(CuratedShowcaseReportPath));
            File.WriteAllText(CuratedShowcaseReportPath, report.ToString(), Encoding.UTF8);
            AssetDatabase.ImportAsset(CuratedShowcaseReportPath);
        }

