        private static string FirstExistingAsset(params string[] candidatePaths)
        {
            foreach (var path in candidatePaths)
            {
                if (!string.IsNullOrEmpty(path) && AssetDatabase.LoadAssetAtPath<Object>(path) != null)
                {
                    return path;
                }
            }

            return null;
        }

        private static void CreateShowcaseMarker(Transform parent, string name, Vector3 position)
        {
            var marker = new GameObject(name);
            marker.transform.SetParent(parent, false);
            marker.transform.localPosition = position;
        }

        private static void CreateShowcaseLabel(Transform parent, string name, string value, Vector3 position, float characterSize)
        {
            var labelObject = new GameObject(name, typeof(TextMesh));
            labelObject.transform.SetParent(parent, false);
            labelObject.transform.localPosition = position;
            var text = labelObject.GetComponent<TextMesh>();
            text.text = value;
            text.anchor = TextAnchor.MiddleCenter;
            text.alignment = TextAlignment.Center;
            text.characterSize = characterSize;
            text.fontSize = 48;
            var renderer = labelObject.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.enabled = false;
            }
        }

        private static int PlaceRoadGrid(Transform parent, List<string> roadModules)
        {
            var placed = 0;
            if (roadModules.Count == 0)
            {
                return placed;
            }

            var positions = new List<Placement>();
            for (var z = -32f; z <= 32f; z += 16f)
            {
                positions.Add(new Placement(new Vector3(0f, 0.16f, z), 0f, 1.55f));
            }

            for (var x = -32f; x <= 32f; x += 16f)
            {
                positions.Add(new Placement(new Vector3(x, 0.17f, 0f), 90f, 1.55f));
            }

            foreach (var corner in new[]
            {
                new Placement(new Vector3(-28f, 0.18f, 28f), 0f, 1.45f),
                new Placement(new Vector3(28f, 0.18f, 28f), 90f, 1.45f),
                new Placement(new Vector3(28f, 0.18f, -28f), 180f, 1.45f),
                new Placement(new Vector3(-28f, 0.18f, -28f), 270f, 1.45f),
            })
            {
                positions.Add(corner);
            }

            for (var i = 0; i < positions.Count; i++)
            {
                var asset = PickRoadAsset(roadModules, i);
                var placement = positions[i];
                if (PlaceAsset(asset, parent, "AssetStore_Road_Module_" + i, placement.Position, placement.Yaw, placement.Scale))
                {
                    placed++;
                }
            }

            return placed;
        }

        private static int PlaceStreetDetails(Transform parent, List<string> streetDetails)
        {
            var placed = 0;
            if (streetDetails.Count == 0)
            {
                return placed;
            }

            var positions = new List<Placement>();
            for (var z = -36f; z <= 36f; z += 12f)
            {
                positions.Add(new Placement(new Vector3(7.8f, 0f, z), -90f, 0.9f));
                positions.Add(new Placement(new Vector3(-7.8f, 0f, z), 90f, 0.9f));
            }

            for (var x = -36f; x <= 36f; x += 12f)
            {
                positions.Add(new Placement(new Vector3(x, 0f, 7.8f), 180f, 0.9f));
                positions.Add(new Placement(new Vector3(x, 0f, -7.8f), 0f, 0.9f));
            }

            positions.Add(new Placement(new Vector3(10.4f, 0f, 10.4f), -45f, 1f));
            positions.Add(new Placement(new Vector3(-10.4f, 0f, 10.4f), 45f, 1f));
            positions.Add(new Placement(new Vector3(10.4f, 0f, -10.4f), -135f, 1f));
            positions.Add(new Placement(new Vector3(-10.4f, 0f, -10.4f), 135f, 1f));

            for (var i = 0; i < positions.Count; i++)
            {
                var asset = streetDetails[i % streetDetails.Count];
                var placement = positions[i];
                if (IsPlayerViewForegroundCorridor(placement.Position))
                {
                    continue;
                }

                if (PlaceAsset(asset, parent, "AssetStore_Street_Detail_" + i, placement.Position, placement.Yaw, placement.Scale))
                {
                    placed++;
                }
            }

            return placed;
        }

        private static bool IsPlayerViewForegroundCorridor(Vector3 position)
        {
            return position.z < -8f && Mathf.Abs(position.x) < 14f;
        }

        private static string PickRoadAsset(List<string> roadModules, int index)
        {
            if (index == 0)
            {
                var crossroad = FirstContaining(roadModules, "road-crossroad-line", "road-crossroad", "road-intersection-line");
                if (!string.IsNullOrEmpty(crossroad))
                {
                    return crossroad;
                }
            }

            var straight = FirstContaining(roadModules, "road-straight", "road_001", "road_002", "road_003", "road_004");
            return string.IsNullOrEmpty(straight) ? roadModules[index % roadModules.Count] : straight;
        }

        private static string FirstContaining(List<string> paths, params string[] terms)
        {
            foreach (var term in terms)
            {
                foreach (var path in paths)
                {
                    if (path.ToLowerInvariant().Contains(term))
                    {
                        return path;
                    }
                }
            }

            return null;
        }

        private static bool PlaceAsset(string path, Transform parent, string prefix, Vector3 position, float yaw, float scaleMultiplier)
        {
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (asset == null)
            {
                return false;
            }

            var instance = (GameObject)PrefabUtility.InstantiatePrefab(asset, SceneManager.GetActiveScene());
            if (instance == null)
            {
                instance = Object.Instantiate(asset);
            }

            instance.name = prefix + "_" + asset.name;
            instance.transform.SetParent(parent, false);
            instance.transform.position = position;
            instance.transform.rotation = Quaternion.Euler(0f, yaw, 0f);
            NormalizeImportedAsset(instance, scaleMultiplier);
            return true;
        }

        private static void NormalizeImportedAsset(GameObject instance, float scaleMultiplier)
        {
            var renderers = instance.GetComponentsInChildren<Renderer>();
            if (renderers.Length == 0)
            {
                return;
            }

            var bounds = renderers[0].bounds;
            for (var i = 1; i < renderers.Length; i++)
            {
                bounds.Encapsulate(renderers[i].bounds);
            }

            var maxSize = Mathf.Max(bounds.size.x, bounds.size.y, bounds.size.z);
            if (maxSize > 0.01f)
            {
                var target = Mathf.Clamp(maxSize, 6f, 20f);
                instance.transform.localScale *= (12f / target) * scaleMultiplier;
            }
        }

        private static void CreateStatusBoard(Transform parent, string message)
        {
            var board = GameObject.CreatePrimitive(PrimitiveType.Cube);
            board.name = "AssetStore_Integration_Status_Board";
            board.transform.SetParent(parent, false);
            board.transform.localPosition = new Vector3(0f, 2f, 46f);
            board.transform.localScale = new Vector3(8f, 3f, 0.2f);

            var labelObject = new GameObject("Status_Text", typeof(TextMesh));
            labelObject.transform.SetParent(board.transform, false);
            labelObject.transform.localPosition = new Vector3(0f, 0f, -0.65f);
            labelObject.transform.localRotation = Quaternion.Euler(0f, 0f, 0f);
            var text = labelObject.GetComponent<TextMesh>();
            text.text = message;
            text.anchor = TextAnchor.MiddleCenter;
            text.alignment = TextAlignment.Center;
            text.characterSize = 0.22f;
            text.fontSize = 48;
            var renderer = labelObject.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.enabled = false;
            }
        }

        private static void CreatePlayerViewFilterAudit(Transform parent)
        {
            var marker = new GameObject("AssetStore_Player_View_Foreground_Filter_Audit");
            marker.transform.SetParent(parent, false);
            marker.transform.localPosition = new Vector3(0f, 0.35f, -18f);

            var textObject = new GameObject("Audit_Text", typeof(TextMesh));
            textObject.transform.SetParent(marker.transform, false);
            textObject.transform.localPosition = new Vector3(0f, 0.5f, 0f);
            var text = textObject.GetComponent<TextMesh>();
            text.text = "asset-store foreground filter\nbulky imported lights skipped";
            text.anchor = TextAnchor.MiddleCenter;
            text.alignment = TextAlignment.Center;
            text.characterSize = 0.12f;
            text.fontSize = 32;
            var renderer = textObject.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.enabled = false;
            }
        }

        private static GameObject FindRoot()
        {
            foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
            {
                if (root.name == "BubuTown_Prototype_All_Visible_Before_Play")
                {
                    return root;
                }
            }

            return null;
        }

        private readonly struct Placement
        {
            public readonly Vector3 Position;
            public readonly float Yaw;
            public readonly float Scale;

            public Placement(Vector3 position, float yaw, float scale)
            {
                Position = position;
                Yaw = yaw;
                Scale = scale;
            }
        }
    }
}
